findings.existing_code:
if let Some(mismatch) = rules_mismatch(manifest) {
    if !failed.is_empty() {
        return Outcome::Failed(failed);
    }
    open.push(mismatch.reason());
    return Outcome::Unverifiable(open);
}

(Some(manifest), Some(coverage)) if coverage.not_judged.is_some() => {
    out.push_str(&format!(
        "baseline: {} claim(s), rules v{} — coverage NOT JUDGED: the manifest declares a \
     different canonical rules version than this build writes (rules v{})\n",
        manifest.claims.len(),
        manifest.rules_v,
        crate::canon::RULES_V
    ))
}

